/**
 * The mandatory message for a view with nothing to show (`design/components/empty-state.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/empty-state.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import {
  Icon,
  MEMBER_PROVIDERS,
  SlotOutlet,
  SlotTemplate,
  useMember,
  type IconProps,
  type IconRole,
  type NodeTemplate,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/empty-state.module.css'
import { Inline, type InlineProps } from '../layout/Inline'

/** The mandatory message for a view with nothing to show: the inputs it takes, by the React member's prop names. */
export interface EmptyStateProps {
  /**
   * What to do about it.
   */
  description?: string
  icon?: IconRole
  /**
   * Describes the situation, such as "No tickets yet" rather than "Empty".
   */
  title: string
  /** The `action` slot's content, for a value of this type another member renders. */
  action?: NodeTemplate
  /** The `secondaryAction` slot's content, for a value of this type another member renders. */
  secondaryAction?: NodeTemplate
}

/** The mandatory message for a view with nothing to show. */
@Component({
  selector: 'pm-empty-state',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [SlotOutlet, SlotTemplate, Icon, Inline],
  // prettier-ignore
  template: `<ng-template pmSlot="action" [pmSlotOf]="$"><ng-content select="[slot=action]" /></ng-template>
<ng-template pmSlot="secondaryAction" [pmSlotOf]="$"><ng-content select="[slot=secondaryAction]" /></ng-template>
<div
[attr.class]="e1()"
data-member="empty-state"
><!-- well -->
<span
[attr.class]="e2()"
><pm-icon
[name]="e3()"
size="lg"
></pm-icon></span>
<!-- title -->
<h2
[attr.class]="e4()"
>{{ e5() }}</h2>
@if (e6()) {<!-- description -->
<p
[attr.class]="e7()"
>{{ e8() }}</p>}
@if (e9()) {<!-- actions -->
<div
[attr.class]="e10()"
><pm-inline
[gap]="e11()"
[wrap]="e12()"
justify="center"
><ng-container [pmSlotOutlet]="'action'" [pmSlotOf]="$" pmSlotInto="default" />
<ng-container [pmSlotOutlet]="'secondaryAction'" [pmSlotOf]="$" pmSlotInto="default" /></pm-inline></div>}</div>`,
})
export class EmptyState {
  /**
   * What to do about it.
   */
  readonly description = input<EmptyStateProps['description']>(undefined)
  readonly icon = input<Exclude<EmptyStateProps['icon'], undefined>, EmptyStateProps['icon']>(
    'inbox',
    { transform: (value: EmptyStateProps['icon']) => (value === undefined ? 'inbox' : value) },
  )
  /**
   * Describes the situation, such as "No tickets yet" rather than "Empty".
   */
  readonly title = input.required<EmptyStateProps['title']>()
  protected readonly $ = useMember({
    events: [],
    props: {
      description: () => this.description(),
      icon: () => this.icon(),
      title: () => this.title(),
    },
  })
  protected readonly $p = this.$.props

  protected e1() {
    return styles.empty
  }

  protected e2() {
    return styles.well
  }

  protected e3(): IconProps['name'] {
    return this.$p.icon
  }

  protected e4() {
    return styles.title
  }

  protected e5() {
    return this.$p.title
  }

  protected e6() {
    return this.$p.description !== undefined
  }

  protected e7() {
    if (!(this.$p.description !== undefined)) return undefined as never
    return styles.description
  }

  protected e8() {
    if (!(this.$p.description !== undefined)) return undefined as never
    return this.$p.description
  }

  protected e9() {
    return this.$.filled('action') || this.$.filled('secondaryAction')
  }

  protected e10() {
    if (!(this.$.filled('action') || this.$.filled('secondaryAction'))) return undefined as never
    return styles.actions
  }

  protected e11(): InlineProps['gap'] {
    if (!(this.$.filled('action') || this.$.filled('secondaryAction'))) return undefined as never
    return 3
  }

  protected e12(): InlineProps['wrap'] {
    if (!(this.$.filled('action') || this.$.filled('secondaryAction'))) return undefined as never
    return true
  }
}
